Translate("esMX", "infiltrator-marksen", {
	title = "Infiltrado Marksen",
	subtitle = "Prisionero de Rocal",
	found = "Rocal, bajo custodia",
	hint = "Busque al prisionero humano retenido en Rocal.",
	allegiance = "Alianza",
	aliases = { "Marksen" },
	sections = {
		{
			title = "Resumen",
			text = [=[Marksen es un espía humano de la {link:alliance}Alianza{/link}, capturado cerca del campamento de los Renegados en el {link:beggar-s-haunt}Refugio de los Mendigos{/link} y retenido como prisionero en {link:stonard}Rocal{/link}. Hace días que no le dejan beber. Suplica clemencia y afirma guardar secretos que van más allá de la propia Alianza: una traición en las altas esferas que, según dice, debe salir a la luz. Los {link:forsaken}Renegados{/link} quieren esos secretos, y no piensan pedirlos con educación.]=],
		},
		{
			title = "Importancia",
			text = [=[El secreto de Marksen une {link:stonard}Rocal{/link} con las disputas ocultas de los reinos. Lo que sabe, y quién más lo sabe, no está registrado.]=],
		},
	},
	chapters = {
		{
			title = "Nada más que la verdad",
			hint = [=[Lleve al prisionero de Rocal una bebida de parte de los Renegados.]=],
			text = [=[El boticario renegado Faustin preparó un suero para soltarle la lengua a un hombre, y el mortacechador Zraedus lo mezcló en una jarra de cerveza. Una jarra de cerveza era lo único que el sediento prisionero no rechazaría. Marksen se la bebió con gusto y empezó a hablar.]=],
		},
	},
	mentions = {
		{ text = "Nada más que la verdad" },
	},
	bonds = {
		{ id = "deathstalker-zraedus", name = "Mortacechador Zraedus", note = "quería sus secretos" },
	},
})

Translate("esMX", "magtoor", {
	title = "Magtoor",
	subtitle = "Voz de El Puerto",
	found = "El Puerto",
	hint = [=[Hable con el draenei que dirige a los exiliados de El Puerto.]=],
	allegiance = "Draenei de El Puerto",
	sections = {
		{
			title = "Resumen",
			text = [=[Magtoor habla por los exiliados draenei de {link:the-harborage}El Puerto{/link}. Su pueblo recorrió un largo camino para llegar a {link:azeroth}Azeroth{/link}, y no todos lo sobrevivieron enteros. Los que perdieron la razón se convirtieron en los perdidos. Tomaron el {link:fallow-sanctuary}Retiro Fangoso{/link} y robaron los cristales sagrados de draenetista de El Puerto. Magtoor teme que, sin esos cristales, su propio pueblo pueda extraviarse también.]=],
		},
		{
			title = "Importancia",
			text = [=[Gracias a Magtoor el mundo sabe lo que son en verdad los perdidos: no monstruos nacidos del pantano, sino un pueblo quebrado por su viaje.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Busca la devolución de la draenetista robada por los perdidos.
• Se alegra de la muerte de {link:noboru-the-cudgel}Noboru{/link}, que aterrorizaba a su pueblo.]=],
		},
	},
	chapters = {
		{
			title = "Los cristales robados",
			hint = "Recupere los cristales de draenetista robados de El Puerto.",
